    <!-- JS Controller -->
    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;

                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupNavDots();
                this.setupBarCharts();

                // Initial update
                this.updateSlide(0);
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            // Trigger bar chart animations if they exist
                            const bars = entry.target.querySelectorAll('.animate-bar');
                            bars.forEach(bar => {
                                setTimeout(() => {
                                    bar.style.width = bar.getAttribute('data-width');
                                }, 600); // Wait for slide reveal
                            });
                        } else {
                            // Optional: Reset when leaving for replayability
                            // entry.target.classList.remove('visible');
                        }
                    });
                }, { threshold: 0.3 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowRight' || e.key === 'Space' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.next();
                    } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.prev();
                    }
                });
            }

            setupNavDots() {
                const container = document.querySelector('.nav-dots');
                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'dot';
                    dot.addEventListener('click', () => {
                        this.slides[index].scrollIntoView({ behavior: 'smooth' });
                        this.updateSlide(index);
                    });
                    container.appendChild(dot);
                });
            }

            setupBarCharts() {
                // Initial width is 0, animated via IntersectionObserver
            }

            next() {
                if (this.currentSlide < this.slides.length - 1) {
                    this.updateSlide(this.currentSlide + 1);
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });
                }
            }

            prev() {
                if (this.currentSlide > 0) {
                    this.updateSlide(this.currentSlide - 1);
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });
                }
            }

            updateSlide(index) {
                this.currentSlide = index;
                const dots = document.querySelectorAll('.dot');
                dots.forEach((dot, i) => {
                    dot.classList.toggle('active', i === index);
                });
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();

            // Handle manual scrolling to update dots
            let scrollTimeout;
            window.addEventListener('scroll', () => {
                clearTimeout(scrollTimeout);
                scrollTimeout = setTimeout(() => {
                    const slides = document.querySelectorAll('.slide');
                    let current = 0;
                    let minDistance = Infinity;

                    slides.forEach((slide, index) => {
                        const rect = slide.getBoundingClientRect();
                        const distance = Math.abs(rect.top);
                        if (distance < minDistance) {
                            minDistance = distance;
                            current = index;
                        }
                    });

                    const dots = document.querySelectorAll('.dot');
                    dots.forEach((dot, i) => {
                        dot.classList.toggle('active', i === current);
                    });
                }, 100);
            });
        });
    </script>
